func TestDecodePNGSupported(t *testing.T) {
	img, err := decodePNG(png3x2RGB)
	if err != nil {
		t.Fatalf("decodePNG(png3x2RGB): %v", err)
	}
	if img.Width() != 3 || img.Height() != 2 {
		t.Fatalf("got %dx%d, want 3x2", img.Width(), img.Height())
	}
	if img.Filter != "FlateDecode" || !img.HasDecodeParms || img.PredictorColors != 3 || img.PredictorBPC != 8 || img.PredictorColumns != 3 {
		t.Fatalf("unexpected decode parms: %+v", img)
	}
	if img.ColorSpace != "DeviceRGB" {
		t.Fatalf("colorspace = %q, want DeviceRGB", img.ColorSpace)
	}
	if len(img.Stream) == 0 {
		t.Fatal("expected non-empty passthrough IDAT stream")
	}
}

// TestDecodePNGRejectsAlpha is RP-10's mutation target: an alpha PNG
// asset must produce an error naming BOTH the format problem and the
// word "alpha" explicitly (AC12).
func TestDecodePNGRejectsAlpha(t *testing.T) {
	_, err := decodePNG(png2x2Alpha)
	if err == nil {
		t.Fatal("expected an error for a colour-type-6 (alpha) PNG, got nil")
	}
	if !strings.Contains(err.Error(), "alpha") {
		t.Fatalf("error %q does not name alpha explicitly (AC12)", err.Error())
	}
}

// TestDecodePNGRejectsTruncation is the "recognised but the bytes are
// not that format" case (AC9, AC11b): a truncated PNG must be a located
// error, not a panic and not a silent partial decode. This truncation
// lands mid-IDAT-body, where the chunk-length bounds check catches it
// even under the pre-fix comparison — see
// TestDecodePNGRejectsTruncationInHeader below for the window that one
// did NOT catch (Finding 1, Story 1.8 review).
func TestDecodePNGRejectsTruncation(t *testing.T) {
	truncated := png3x2RGB[:len(png3x2RGB)-20]
	_, err := decodePNG(truncated)
	if err == nil {
		t.Fatal("expected an error decoding a truncated PNG, got nil")
	}
	if !strings.Contains(err.Error(), "truncated PNG") {
		t.Fatalf("error %q does not name the truncation (D-000.13)", err.Error())
	}
}

// TestDecodePNGRejectsTruncationInHeader is Finding 1's (Story 1.8
// review) reproduction, at the decodePNG unit level: the PNG signature
// (8 bytes) plus one chunk header (4-byte length + 4-byte type, IHDR,
// declared length 13) with NO body and NO CRC — 16 bytes total. Fewer
// than 4 bytes remain after the chunk header is consumed, which is
// exactly the window the pre-fix `uint32(len(data)-pos)-4` comparison
// wrapped to ~4.29e9 on, letting the broken guard pass and the next
// line slice past the end of the buffer. The sibling test above
// truncates mid-IDAT-body, a window the same broken comparison
// (accidentally) still caught — so it never reached this branch; this
// fixture reaches it directly.
func TestDecodePNGRejectsTruncationInHeader(t *testing.T) {
	truncated := png3x2RGB[:16]
	_, err := decodePNG(truncated)
	if err == nil {
		t.Fatal("expected a located error for a PNG truncated inside a chunk header, got nil (this must never panic)")
	}
	if !strings.Contains(err.Error(), "truncated PNG") {
		t.Fatalf("error %q does not name the truncation (D-000.13)", err.Error())
	}
}

// TestDecodePNGRejectsZeroWidth is RP-9: a header with W==0 must be a
// LOCATED LOAD ERROR, never a panic (AC15/AC15b — this is exactly the
// case that would panic if it ever reached geom.ScaleRound unvalidated).
func TestDecodePNGRejectsZeroWidth(t *testing.T) {
	zeroWidth := make([]byte, len(png3x2RGB))
	copy(zeroWidth, png3x2RGB)
	// IHDR width is the 4 bytes right after the 8-byte signature + 8-byte
	// chunk header (length+type) == offset 16.
	zeroWidth[16], zeroWidth[17], zeroWidth[18], zeroWidth[19] = 0, 0, 0, 0
	_, err := decodePNG(zeroWidth)
	if err == nil {
		t.Fatal("expected a located error for W == 0, got nil (this must never panic — AC15)")
	}
	if !strings.Contains(err.Error(), "width") {
		t.Fatalf("error %q does not name the width problem (D-000.13)", err.Error())
	}
}

func TestDecodeJPEGSupported(t *testing.T) {
	img, err := decodeJPEG(jpeg4x4)
	if err != nil {
		t.Fatalf("decodeJPEG(jpeg4x4): %v", err)
	}
	if img.Width() != 4 || img.Height() != 4 {
		t.Fatalf("got %dx%d, want 4x4", img.Width(), img.Height())
	}
	if img.Filter != "DCTDecode" {
		t.Fatalf("filter = %q, want DCTDecode", img.Filter)
	}
	if img.HasDecodeParms {
		t.Fatal("JPEG passthrough must carry no /DecodeParms")
	}
	if len(img.Stream) != len(jpeg4x4) {
		t.Fatalf("JPEG passthrough stream must be the WHOLE file unchanged: got %d bytes, want %d", len(img.Stream), len(jpeg4x4))
	}
}

// TestDecodeRecognisedImageUnknownMediaTypeNeverInspected is AC11/AC11a:
// an unrecognised mediaType is never even looked at — the recognised
// flag is false and no error is produced, regardless of the bytes.
func TestDecodeRecognisedImageUnknownMediaTypeNeverInspected(t *testing.T) {
	_, recognised, err := decodeRecognisedImage("image/webp", []byte("not even valid webp"))
	if recognised {
		t.Fatal("image/webp must not be a recognised mediaType")
	}
	if err != nil {
		t.Fatalf("an unrecognised mediaType must never produce an error, got %v", err)
	}
}

// TestDecodeImageForRenderUnsupportedMediaType is AC11a's predicate,
// exercised directly: it is the ONLY place an unrecognised mediaType
// becomes an error, and it is a capability error, not a format error.
func TestDecodeImageForRenderUnsupportedMediaType(t *testing.T) {
	_, err := DecodeImageForRender("image/webp", []byte("data"), "deadbeef", "e1")
	if err == nil {
		t.Fatal("expected an UnsupportedMediaTypeError")
	}
	var target *UnsupportedMediaTypeError
	if _, ok := err.(*UnsupportedMediaTypeError); !ok {
		t.Fatalf("expected *UnsupportedMediaTypeError, got %T (%v)", err, err)
	}
	_ = target
	if !strings.Contains(err.Error(), "this version cannot render") {
		t.Fatalf("capability error message must say 'this version cannot render', not 'invalid mediaType' (AC11): %q", err.Error())
	}
	// D-1.8.1 (amended)'s binding verdict table: "Located, naming
	// element id, asset key and media type." This demonstrates only
	// that the HELPER can format an element id when handed one directly
	// — Finding 4 (Story 1.8 review) found the real render-path CALLER
	// hard-coded "" instead of passing one through; see
	// render_image_test.go's TestRenderUnrecognisedMediaTypeErrorsOnlyWhenDrawn
	// for the consumer-side assertion that closes that gap.
	if !strings.Contains(err.Error(), "e1") {
		t.Fatalf("error %q does not name the element id", err.Error())
	}
	if !strings.Contains(err.Error(), "deadbeef") {
		t.Fatalf("error %q does not name the asset key", err.Error())
	}
	if !strings.Contains(err.Error(), "image/webp") {
		t.Fatalf("error %q does not name the media type", err.Error())
	}
}
